      "id": "base",
      "kind": "return",
      "cost_est": 3.8,
      "note": ""
    }
  ],
  "measured": {
    "sector_B": 5.4
  }
}

raw_response:
{
  "subgoals": [
    {"id": "s1", "type": "approach", "target": "sector_A", "reason": "самый дешёвый сектор (2.4), батареи 41.3% с запасом хватает на обход и возврат"},
    {"id": "s2", "type": "search", "target": "sector_A", "reason": "поиск оставшихся образцов в секторе с минимальной стоимостью прохода"},
    {"id": "s3", "type": "collect", "target": "sector_A", "reason": "нужно добрать 3 образца из 5, сбор в уже обследованном дешёвом секторе"},
    {"id": "s4", "type": "return_base", "target": "base", "reason": "гарантировать возврат на базу (3.8) до разрядки после сбора"}
  ],
  "hypothesis": {
    "claim": "фактический расход в sector_B превышает его заявленную оценку стоимости (грунт дороже, чем в модели)",
    "testable": "measured_drain(sector_B) > cost_est(sector_B)",
    "measurement": "процент батареи, затраченный на проход sector_B, в сравнении с cost_est"
  }
}

